use std :: process :: Command ; use std :: fs ; use std :: path :: Path ; fn test_mathematical_calculations () -> IntegrationTestResult { let start = std :: time :: Instant :: now () ; let mut total_complexity = 0.0 ; let mut total_repos = 0 ; for _i in 0 .. 3 { match Command :: new ("./simple_repository_mathematical_atlas") . output () { Ok (output) => { if output . status . success () { match fs :: read_to_string ("repository_atlas_output/simple_complete_atlas.md") { Ok (content) => { if content . contains ("Average Complexity") { total_repos += 1 ; } } Err (_) => { } } } } Err (_) => { } } } if total_repos >= 2 { IntegrationTestResult :: new ("Mathematical Calculations" . to_string () , true , start . elapsed () . as_millis () as u64 , None) } else { IntegrationTestResult :: new ("Mathematical Calculations" . to_string () , false , start . elapsed () . as_millis () as u64 , Some (format ! ("Only {} successful mathematical calculations out of 3" , total_repos))) } }